// Appends rows to staticFormationSlotInfos and assigns FormationInfoRecord.slotRange.
inline bool AppendFormationInfoRecordSlotRange(FormationInfoRecord* parent, VoxRlStaticData* data, const std::vector<FormationSlotInfoRecord>& rows)
{
    if (parent == 0 || data == 0 || !VoxRlBuilderSizeFitsU32(data->staticFormationSlotInfos.size()) || !VoxRlBuilderSizeFitsU32(rows.size())) return false;
    const u32 first = static_cast<u32>(data->staticFormationSlotInfos.size());
    const u32 count = static_cast<u32>(rows.size());
    u32 end = 0; if (!VoxRlAddU32(first, count, end)) return false;
    data->staticFormationSlotInfos.insert(data->staticFormationSlotInfos.end(), rows.begin(), rows.end());
    parent->slotRangeFirst = first; parent->slotRangeCount = count; return true;
}

inline bool VoxRlValidateStaticData(const VoxRlStaticData& data, VoxRlBuilderValidationFailure* failure)
{
    if (failure != 0) *failure = VoxRlBuilderValidationFailure();
    if (true && !VoxRlIsValidStaticRulesRecord(data.staticRules)) return VoxRlBuilderValidationFail(failure, "staticRules", "record", static_cast<size_t>(-1));
    if (!VoxRlBuilderSizeFitsU32(data.staticHandicapInfo.size())) return VoxRlBuilderValidationFail(failure, "staticHandicapInfo", "size", static_cast<size_t>(-1));
    if (!VoxRlBuilderSizeFitsU32(data.staticTerrainInfos.size())) return VoxRlBuilderValidationFail(failure, "staticTerrainInfos", "size", static_cast<size_t>(-1));
    if (!VoxRlBuilderSizeFitsU32(data.staticFeatureInfos.size())) return VoxRlBuilderValidationFail(failure, "staticFeatureInfos", "size", static_cast<size_t>(-1));
    if (!VoxRlBuilderSizeFitsU32(data.staticRouteInfos.size())) return VoxRlBuilderValidationFail(failure, "staticRouteInfos", "size", static_cast<size_t>(-1));
    if (!VoxRlBuilderSizeFitsU32(data.staticImprovementInfos.size())) return VoxRlBuilderValidationFail(failure, "staticImprovementInfos", "size", static_cast<size_t>(-1));
    if (!VoxRlBuilderSizeFitsU32(data.staticResourceInfos.size())) return VoxRlBuilderValidationFail(failure, "staticResourceInfos", "size", static_cast<size_t>(-1));
    if (!VoxRlBuilderSizeFitsU32(data.staticUnitEntryInfos.size())) return VoxRlBuilderValidationFail(failure, "staticUnitEntryInfos", "size", static_cast<size_t>(-1));
    if (!VoxRlBuilderSizeFitsU32(data.staticPlotTopology.size())) return VoxRlBuilderValidationFail(failure, "staticPlotTopology", "size", static_cast<size_t>(-1));
    for (size_t rowIndex = 0; rowIndex < data.staticPlotTopology.size(); ++rowIndex) if (!VoxRlIsValidPlotTopologyRecord(data.staticPlotTopology[rowIndex])) return VoxRlBuilderValidationFail(failure, "staticPlotTopology", "record", rowIndex);
    if (!VoxRlBuilderSizeFitsU32(data.staticPromotionInfos.size())) return VoxRlBuilderValidationFail(failure, "staticPromotionInfos", "size", static_cast<size_t>(-1));
    if (!VoxRlBuilderSizeFitsU32(data.staticProcessInfos.size())) return VoxRlBuilderValidationFail(failure, "staticProcessInfos", "size", static_cast<size_t>(-1));
    if (!VoxRlBuilderSizeFitsU32(data.staticCityEventChoiceInfos.size())) return VoxRlBuilderValidationFail(failure, "staticCityEventChoiceInfos", "size", static_cast<size_t>(-1));
    if (!VoxRlBuilderSizeFitsU32(data.staticBeliefInfos.size())) return VoxRlBuilderValidationFail(failure, "staticBeliefInfos", "size", static_cast<size_t>(-1));
    if (!VoxRlBuilderSizeFitsU32(data.staticBuildInfos.size())) return VoxRlBuilderValidationFail(failure, "staticBuildInfos", "size", static_cast<size_t>(-1));
    if (!VoxRlBuilderSizeFitsU32(data.staticUnitClassInfos.size())) return VoxRlBuilderValidationFail(failure, "staticUnitClassInfos", "size", static_cast<size_t>(-1));
    if (!VoxRlBuilderSizeFitsU32(data.staticFormationInfos.size())) return VoxRlBuilderValidationFail(failure, "staticFormationInfos", "size", static_cast<size_t>(-1));
    for (size_t index = 0; index < data.staticFormationInfos.size(); ++index) {
        if (!VoxRlBuilderRangeFits(data.staticFormationInfos[index].slotRangeFirst, data.staticFormationInfos[index].slotRangeCount, data.staticFormationSlotInfos.size())) return VoxRlBuilderValidationFail(failure, "staticFormationInfos", "slotRange range", index);
    }
    if (!VoxRlBuilderSizeFitsU32(data.staticFormationSlotInfos.size())) return VoxRlBuilderValidationFail(failure, "staticFormationSlotInfos", "size", static_cast<size_t>(-1));
    for (size_t rowIndex = 0; rowIndex < data.staticFormationSlotInfos.size(); ++rowIndex) if (!VoxRlIsValidFormationSlotInfoRecord(data.staticFormationSlotInfos[rowIndex])) return VoxRlBuilderValidationFail(failure, "staticFormationSlotInfos", "record", rowIndex);
    if (!VoxRlBuilderSizeFitsU32(data.staticUnitResourceRequirements.size())) return VoxRlBuilderValidationFail(failure, "staticUnitResourceRequirements", "size", static_cast<size_t>(-1));
    if (!VoxRlBuilderSizeFitsU32(data.staticImprovementResourceCompatibilities.size())) return VoxRlBuilderValidationFail(failure, "staticImprovementResourceCompatibilities", "size", static_cast<size_t>(-1));
    if (!VoxRlBuilderSizeFitsU32(data.staticFlavorInfos.size())) return VoxRlBuilderValidationFail(failure, "staticFlavorInfos", "size", static_cast<size_t>(-1));
    if (!VoxRlBuilderSizeFitsU32(data.staticFlavorNames.size())) return VoxRlBuilderValidationFail(failure, "staticFlavorNames", "size", static_cast<size_t>(-1));
    if (!VoxRlBuilderSizeFitsU32(data.staticSpecialUnitInfos.size())) return VoxRlBuilderValidationFail(failure, "staticSpecialUnitInfos", "size", static_cast<size_t>(-1));
    if (!VoxRlBuilderSizeFitsU32(data.staticUnitEraCombats.size())) return VoxRlBuilderValidationFail(failure, "staticUnitEraCombats", "size", static_cast<size_t>(-1));
    for (size_t rowIndex = 0; rowIndex < data.staticUnitEraCombats.size(); ++rowIndex) if (!VoxRlIsValidUnitEraCombatRecord(data.staticUnitEraCombats[rowIndex])) return VoxRlBuilderValidationFail(failure, "staticUnitEraCombats", "record", rowIndex);
    if (!VoxRlBuilderSizeFitsU32(data.staticUnitEraPromotions.size())) return VoxRlBuilderValidationFail(failure, "staticUnitEraPromotions", "size", static_cast<size_t>(-1));
    for (size_t rowIndex = 0; rowIndex < data.staticUnitEraPromotions.size(); ++rowIndex) if (!VoxRlIsValidUnitEraPromotionRecord(data.staticUnitEraPromotions[rowIndex])) return VoxRlBuilderValidationFail(failure, "staticUnitEraPromotions", "record", rowIndex);
    if (!VoxRlBuilderSizeFitsU32(data.staticPromotionTypes.size())) return VoxRlBuilderValidationFail(failure, "staticPromotionTypes", "size", static_cast<size_t>(-1));
    for (size_t rowIndex = 0; rowIndex < data.staticPromotionTypes.size(); ++rowIndex) if (!VoxRlIsValidPromotionTypeRecord(data.staticPromotionTypes[rowIndex])) return VoxRlBuilderValidationFail(failure, "staticPromotionTypes", "record", rowIndex);
    if (!VoxRlBuilderSizeFitsU32(data.staticPromotionTypeNames.size())) return VoxRlBuilderValidationFail(failure, "staticPromotionTypeNames", "size", static_cast<size_t>(-1));
    if (!VoxRlBuilderSizeFitsU32(data.staticPromotionPlagues.size())) return VoxRlBuilderValidationFail(failure, "staticPromotionPlagues", "size", static_cast<size_t>(-1));
    for (size_t rowIndex = 0; rowIndex < data.staticPromotionPlagues.size(); ++rowIndex) if (!VoxRlIsValidPromotionPlagueRecord(data.staticPromotionPlagues[rowIndex])) return VoxRlBuilderValidationFail(failure, "staticPromotionPlagues", "record", rowIndex);
    if (!VoxRlBuilderSizeFitsU32(data.staticPromotionBlockedPromotions.size())) return VoxRlBuilderValidationFail(failure, "staticPromotionBlockedPromotions", "size", static_cast<size_t>(-1));
    for (size_t rowIndex = 0; rowIndex < data.staticPromotionBlockedPromotions.size(); ++rowIndex) if (!VoxRlIsValidPromotionBlockedPromotionRecord(data.staticPromotionBlockedPromotions[rowIndex])) return VoxRlBuilderValidationFail(failure, "staticPromotionBlockedPromotions", "record", rowIndex);
    u32 staticFormationSlotInfosCursor = 0;
    for (size_t parentIndex = 0; parentIndex < data.staticFormationInfos.size(); ++parentIndex) {
        const FormationInfoRecord& parent = data.staticFormationInfos[parentIndex];
        if (parent.slotRangeFirst != staticFormationSlotInfosCursor || !VoxRlAddU32(staticFormationSlotInfosCursor, parent.slotRangeCount, staticFormationSlotInfosCursor)) return VoxRlBuilderValidationFail(failure, "staticFormationInfos", "slotRange partition", parentIndex);
    }
    if (staticFormationSlotInfosCursor != static_cast<u32>(data.staticFormationSlotInfos.size())) return VoxRlBuilderValidationFail(failure, "staticFormationSlotInfos", "partition tail", static_cast<size_t>(-1));
    return true;
}

inline bool VoxRlValidateStaticData(const VoxRlStaticData& data)
{
    return VoxRlValidateStaticData(data, 0);
}

inline void VoxRlStaticData::Clear()
{
    staticRules = StaticRulesRecord();
    staticHandicapInfo.clear();
    staticTerrainInfos.clear();
    staticFeatureInfos.clear();
    staticRouteInfos.clear();
    staticImprovementInfos.clear();
    staticResourceInfos.clear();
    staticUnitEntryInfos.clear();
    staticBuildIds = StaticBuildIdsRecord();
    staticMapTopology = MapTopologyRecord();
    staticPlotTopology.clear();
    staticPromotionInfos.clear();
    staticProcessInfos.clear();
    staticCityEventChoiceInfos.clear();
    staticBeliefInfos.clear();
    staticBuildInfos.clear();
    staticUnitClassInfos.clear();
    staticFormationInfos.clear();
    staticFormationSlotInfos.clear();
    staticUnitResourceRequirements.clear();
    staticImprovementResourceCompatibilities.clear();
    staticFlavorInfos.clear();
    staticFlavorNames.clear();
    staticSpecialUnitInfos.clear();
    staticUnitEraCombats.clear();
    staticUnitEraPromotions.clear();
    staticPromotionTypes.clear();
    staticPromotionTypeNames.clear();
    staticPromotionPlagues.clear();
    staticPromotionBlockedPromotions.clear();
}

