inline bool VoxRlStaticData::Write(const VoxRlBlockIdentity& identity, VoxRlOwnedBlockStorage* storage, u32* byteLength) const
{
    u32 required = 0;
    if (storage == 0 || !ByteLength(&required) || !storage->Allocate(required)) return false;
    return Write(identity, storage->MutableBytes(), storage->ByteLength(), byteLength);
}

inline bool VoxRlStaticData::Write(const VoxRlBlockIdentity& identity, VoxRlOwnedBlockStorage& storage, u32& byteLength) const
{
    return Write(identity, &storage, &byteLength);
}

// Appends rows to campaignThreatenedCities and assigns CampaignHeaderRecord.threatenedCityRange.
inline bool AppendCampaignHeaderRecordThreatenedCityRange(CampaignHeaderRecord* parent, VoxRlCampaignData* data, const std::vector<CampaignThreatenedCityRecord>& rows)
{
    if (parent == 0 || data == 0 || !VoxRlBuilderSizeFitsU32(data->campaignThreatenedCities.size()) || !VoxRlBuilderSizeFitsU32(rows.size())) return false;
    const u32 first = static_cast<u32>(data->campaignThreatenedCities.size());
    const u32 count = static_cast<u32>(rows.size());
    u32 end = 0; if (!VoxRlAddU32(first, count, end)) return false;
    data->campaignThreatenedCities.insert(data->campaignThreatenedCities.end(), rows.begin(), rows.end());
    parent->threatenedCityRangeFirst = first; parent->threatenedCityRangeCount = count; return true;
}

