// Appends rows to worldRevealedOverrides and assigns PlotTeamRecord.revealedOverrideRange.
inline bool AppendPlotTeamRecordRevealedOverrideRange(PlotTeamRecord* parent, VoxRlWorldData* data, const std::vector<RevealedOverrideRecord>& rows)
{
    if (parent == 0 || data == 0 || !VoxRlBuilderSizeFitsU32(data->worldRevealedOverrides.size()) || !VoxRlBuilderSizeFitsU32(rows.size())) return false;
    const u32 first = static_cast<u32>(data->worldRevealedOverrides.size());
    const u32 count = static_cast<u32>(rows.size());
    u32 end = 0; if (!VoxRlAddU32(first, count, end)) return false;
    data->worldRevealedOverrides.insert(data->worldRevealedOverrides.end(), rows.begin(), rows.end());
    parent->revealedOverrideRangeFirst = first; parent->revealedOverrideRangeCount = count; return true;
}

