inline bool VoxRlWorldData::Write(const VoxRlBlockIdentity& identity, VoxRlOwnedBlockStorage* storage, u32* byteLength) const
{
    u32 required = 0;
    if (storage == 0 || !ByteLength(&required) || !storage->Allocate(required)) return false;
    return Write(identity, storage->MutableBytes(), storage->ByteLength(), byteLength);
}

inline bool VoxRlWorldData::Write(const VoxRlBlockIdentity& identity, VoxRlOwnedBlockStorage& storage, u32& byteLength) const
{
    return Write(identity, &storage, &byteLength);
}

