        if (!VoxRlMultiplyU32(static_cast<u32>(replayAssignmentDamage.size()), sizeof(ReplayAssignmentDamageRecord), length) || !VoxRlAlignU32(offset, offset) || !VoxRlAddU32(offset, length, offset)) return false;
